  blur += sceneTap(uv + vec2(-r,  r * 0.72)) * 0.075;
  blur += sceneTap(uv + vec2( r, -r * 0.72)) * 0.075;
  blur += sceneTap(uv + vec2(-r, -r * 0.72)) * 0.075;
